#!/usr/bin/env python3
"""
validate_m2.py

This script verifies that every JSON file in data/output/ conforms to the
expected M2 schema for the "email_classifier" and "form_sync" workflows.
The schema is intentionally simple for demonstration purposes:

{
    "workflow_name": str,
    "status": str,           # "success" or "failure"
    "results": { ... }       # arbitrary nested dict
}
"""

import json
import os
import sys
from pathlib import Path

# Expected keys in the top-level JSON object
REQUIRED_KEYS = {"workflow_name", "status", "results"}

def load_json(path: Path):
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception as e:
        raise ValueError(f"Failed to load JSON from {path}: {e}")

def validate_schema(obj, path: Path):
    if not isinstance(obj, dict):
        raise ValueError(f"{path}: Top-level object must be a dict")
    missing = REQUIRED_KEYS - obj.keys()
    if missing:
        raise ValueError(f"{path}: Missing required keys: {missing}")
    if obj["workflow_name"] not in {"email_classifier", "form_sync"}:
        raise ValueError(f"{path}: Invalid workflow_name '{obj['workflow_name']}'")
    if obj["status"] not in {"success", "failure"}:
        raise ValueError(f"{path}: Invalid status '{obj['status']}'")
    # results can be any JSON value; no further checks here

def main():
    output_dir = Path("data/output")
    if not output_dir.is_dir():
        print(f"[ERROR] Output directory not found: {output_dir}")
        sys.exit(1)

    json_files = list(output_dir.rglob("*.json"))
    if not json_files:
        print("[ERROR] No JSON files found in data/output/")
        sys.exit(1)

    for js_file in json_files:
        try:
            obj = load_json(js_file)
            validate_schema(obj, js_file)
        except Exception as e:
            print(f"[FAIL] {js_file}: {e}")
            sys.exit(1)

    print("Validation succeeded: All JSON files conform to the schema.")
    sys.exit(0)

if __name__ == "__main__":
    main()

